import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

namespace cute_conv3d_detail {

constexpr int TILE_OC = 8;
constexpr int TILE_POS = 32;
constexpr int TILE_K = 8;

__global__ void cute_conv3d_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int KD,
    int KH,
    int KW,
    int OD,
    int OH,
    int OW,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    __shared__ float smem_weight[TILE_OC * TILE_K];

    const int tid = threadIdx.x;
    const int local_oc = tid % TILE_OC;
    const int local_pos = tid / TILE_OC;

    const int oc = blockIdx.y * TILE_OC + local_oc;
    const int flat_pos = blockIdx.x * TILE_POS + local_pos;

    const int spatial_out = OD * OH * OW;
    const int total_positions = N * spatial_out;

    const bool valid_oc = oc < OC;
    const bool valid_pos = flat_pos < total_positions;

    int n = 0;
    int od = 0;
    int oh = 0;
    int ow = 0;

    if (valid_pos) {
        n = flat_pos / spatial_out;
        int rem = flat_pos - n * spatial_out;
        od = rem / (OH * OW);
        rem -= od * OH * OW;
        oh = rem / OW;
        ow = rem - oh * OW;
    }

    const int kernel_volume = KD * KH * KW;
    const int ic_per_group = IC / groups;
    const int reduction = ic_per_group * kernel_volume;
    const int group = valid_oc ? (oc / (OC / groups)) : 0;
    const int input_channel_base = group * ic_per_group;

    auto gX = make_tensor(
        make_gmem_ptr(x),
        make_shape(N, IC, ID, IH, IW),
        make_stride(IC * ID * IH * IW, ID * IH * IW, IH * IW, IW, 1));

    auto gW = make_tensor(
        make_gmem_ptr(weight),
        make_shape(OC, ic_per_group, KD, KH, KW),
        make_stride(ic_per_group * kernel_volume,
                    kernel_volume,
                    KH * KW,
                    KW,
                    1));

    float acc = 0.0f;

    for (int k0 = 0; k0 < reduction; k0 += TILE_K) {
        if (tid < TILE_OC * TILE_K) {
            const int w_oc = tid / TILE_K;
            const int w_k = tid % TILE_K;
            const int global_oc = blockIdx.y * TILE_OC + w_oc;
            const int global_k = k0 + w_k;

            float value = 0.0f;
            if (global_oc < OC && global_k < reduction) {
                const int ic = global_k / kernel_volume;
                int kr = global_k - ic * kernel_volume;
                const int kd = kr / (KH * KW);
                kr -= kd * KH * KW;
                const int kh = kr / KW;
                const int kw = kr - kh * KW;

                value = gW(global_oc, ic, kd, kh, kw);
            }

            auto sW = make_tensor(
                make_smem_ptr(smem_weight),
                make_shape(Int<TILE_OC>{}, Int<TILE_K>{}),
                make_stride(Int<TILE_K>{}, Int<1>{}));

            sW(w_oc, w_k) = value;
        }

        __syncthreads();

        if (valid_oc && valid_pos) {
            auto sW = make_tensor(
                make_smem_ptr(smem_weight),
                make_shape(Int<TILE_OC>{}, Int<TILE_K>{}),
                make_stride(Int<TILE_K>{}, Int<1>{}));

            for (int lk = 0; lk < TILE_K; ++lk) {
                const int global_k = k0 + lk;
                if (global_k >= reduction) {
                    break;
                }

                const int ic = global_k / kernel_volume;
                int kr = global_k - ic * kernel_volume;
                const int kd = kr / (KH * KW);
                kr -= kd * KH * KW;
                const int kh = kr / KW;
                const int kw = kr - kh * KW;

                const int id = od * stride - padding + kd * dilation;
                const int ih = oh * stride - padding + kh * dilation;
                const int iw = ow * stride - padding + kw * dilation;

                float input_value = 0.0f;
                if (id >= 0 && id < ID &&
                    ih >= 0 && ih < IH &&
                    iw >= 0 && iw < IW) {
                    input_value = gX(
                        n,
                        input_channel_base + ic,
                        id,
                        ih,
                        iw);
                }

                acc += input_value * sW(local_oc, lk);
            }
        }

        __syncthreads();
    }

    if (valid_oc && valid_pos) {
        if (bias != nullptr) {
            acc += bias[oc];
        }

        out[
            (((n * OC + oc) * OD + od) * OH + oh) * OW + ow
        ] = acc;
    }
}

} // namespace cute_conv3d_detail

torch::Tensor cute_conv3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    int64_t groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

    TORCH_CHECK(x.dim() == 5, "x must have shape [N, C, D, H, W]");
    TORCH_CHECK(weight.dim() == 5, "weight must have shape [OC, IC/groups, KD, KH, KW]");
    TORCH_CHECK(groups > 0, "groups must be positive");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    const int N = static_cast<int>(x_c.size(0));
    const int IC = static_cast<int>(x_c.size(1));
    const int ID = static_cast<int>(x_c.size(2));
    const int IH = static_cast<int>(x_c.size(3));
    const int IW = static_cast<int>(x_c.size(4));

    const int OC = static_cast<int>(w_c.size(0));
    const int ic_per_group = static_cast<int>(w_c.size(1));
    const int KD = static_cast<int>(w_c.size(2));
    const int KH = static_cast<int>(w_c.size(3));
    const int KW = static_cast<int>(w_c.size(4));

    TORCH_CHECK(IC % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(OC % groups == 0, "output channels must be divisible by groups");
    TORCH_CHECK(ic_per_group == IC / groups,
                "weight channel dimension does not match groups");

    const int OD = (ID + 2 * padding - dilation * (KD - 1) - 1) / stride + 1;
    const int OH = (IH + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
    const int OW = (IW + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;

    TORCH_CHECK(OD > 0 && OH > 0 && OW > 0,
                " convolution output dimensions must be positive");

    const bool has_bias = b_c.numel() != 0;
    if (has_bias) {
        TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC,
                    "bias must have shape [out_channels]");
    }

    auto out = torch::empty(
        {N, OC, OD, OH, OW},
        x_c.options());

    const int total_positions = N * OD * OH * OW;
    const int grid_x = (total_positions + cute_conv3d_detail::TILE_POS - 1) / cute_conv3d_detail::TILE_POS;
    const int grid_y = (OC + cute_conv3d_detail::TILE_OC - 1) / cute_conv3d_detail::TILE_OC;

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv3d_detail::cute_conv3d_kernel<<<
        dim3(grid_x, grid_y, 1),
        dim3(cute_conv3d_detail::TILE_OC * cute_conv3d_detail::TILE_POS, 1, 1),
        0,
        stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        has_bias ? b_c.data_ptr<float>() : nullptr,
        out.data_ptr<float>(),
        N,
        IC,
        ID,
        IH,
        IW,
        OC,
        KD,
        KH,
        KW,
        OD,
        OH,
        OW,
        static_cast<int>(stride),
        static_cast<int>(padding),
        static_cast<int>(dilation),
        static_cast<int>(groups));

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "cute_conv3d kernel launch failed");

    return out;
}
"""


cute_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv3d"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv3d = nn.Conv3d(
            in_channels,
            out_channels,
            (kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.conv3d.bias is None:
            bias = torch.empty(
                (0,),
                device=x.device,
                dtype=x.dtype,
            )
        else:
            bias = self.conv3d.bias

        return cute_ext.cute_conv3d(
            x,
            self.conv3d.weight,
            bias,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )

